{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2167-01-08 02:15:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee. I’ll be taking care of you tonight. Can you tell me what brought you to the hospital?"
    },
    {
      "turn_number": 2,
      "time": "2167-01-08 02:17:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. I’ve had this dull feeling in my stomach for two days now. It’s not really pain, but it’s constant. It feels just like the discomfort I had before my bypass surgery."
    },
    {
      "turn_number": 3,
      "time": "2167-01-08 02:19:00",
      "speaker": "Doctor",
      "text": "I see. That’s concerning, especially with your history. But you’re not having nausea, vomiting, or shortness of breath?"
    },
    {
      "turn_number": 4,
      "time": "2167-01-08 02:20:00",
      "speaker": "Patient",
      "text": "No, none of that. It doesn’t get worse with activity or better with rest. And it’s not related to food. But I’ve been under a lot of stress lately."
    },
    {
      "turn_number": 5,
      "time": "2167-01-08 02:22:00",
      "speaker": "Doctor",
      "text": "I understand. You mentioned stress—can you tell me more about that?"
    },
    {
      "turn_number": 6,
      "time": "2167-01-08 02:24:00",
      "speaker": "Patient",
      "text": "My son can’t care for my grandson anymore, and I don’t know where he’ll go. I can’t take care of him long-term—I’m 70, and my health isn’t great. It’s breaking my heart."
    },
    {
      "turn_number": 7,
      "time": "2167-01-08 02:26:00",
      "speaker": "Doctor",
      "text": "That sounds incredibly difficult. We’ve already checked your heart—your EKG and blood tests, including troponin, were normal. Twice."
    },
    {
      "turn_number": 8,
      "time": "2167-01-08 02:28:00",
      "speaker": "Patient",
      "text": "So it’s not my heart? But it feels just like before my bypass."
    },
    {
      "turn_number": 9,
      "time": "2167-01-08 02:30:00",
      "speaker": "Doctor",
      "text": "I know it’s scary. Sometimes people with heart disease feel stomach discomfort instead of chest pain—it’s called an anginal equivalent. But your tests are reassuring."
    },
    {
      "turn_number": 10,
      "time": "2167-01-08 04:10:00",
      "speaker": "Doctor",
      "text": "We gave you a medication called pantoprazole earlier. How’s the discomfort now?"
    },
    {
      "turn_number": 11,
      "time": "2167-01-08 04:12:00",
      "speaker": "Patient",
      "text": "Actually, it’s a bit better. Not gone, but not as heavy."
    },
    {
      "turn_number": 12,
      "time": "2167-01-08 04:14:00",
      "speaker": "Doctor",
      "text": "That’s a good sign. We also did a chest X-ray—no signs of heart failure or infection. And your stress test came back normal—no EKG changes, no symptoms during exercise."
    },
    {
      "turn_number": 13,
      "time": "2167-01-08 04:16:00",
      "speaker": "Patient",
      "text": "So it’s not my heart. Then what is it?"
    },
    {
      "turn_number": 14,
      "time": "2167-01-08 04:18:00",
      "speaker": "Doctor",
      "text": "It’s likely dyspepsia—stomach discomfort not from heart issues. It can be worsened by stress, which you’re clearly under. We’re treating it with pantoprazole to reduce stomach acid."
    },
    {
      "turn_number": 15,
      "time": "2167-01-08 10:30:00",
      "speaker": "Doctor",
      "text": "Your blood pressure has been a bit high during your stay. We’re increasing your lisinopril from 5mg to 10mg to help with that."
    },
    {
      "turn_number": 16,
      "time": "2167-01-08 10:32:00",
      "speaker": "Patient",
      "text": "Is that safe with my other meds?"
    },
    {
      "turn_number": 17,
      "time": "2167-01-08 10:34:00",
      "speaker": "Doctor",
      "text": "Yes, it’s safe and important for your heart health. We’re keeping all your other medications the same—atorvastatin, metoprolol, aspirin, and your thyroid pill."
    },
    {
      "turn_number": 18,
      "time": "2167-01-08 15:10:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re going to discharge you soon. You’ll stay on pantoprazole and the higher dose of lisinopril."
    },
    {
      "turn_number": 19,
      "time": "2167-01-08 15:12:00",
      "speaker": "Patient",
      "text": "And my heart? Should I worry?"
    },
    {
      "turn_number": 20,
      "time": "2167-01-08 15:14:00",
      "speaker": "Doctor",
      "text": "No, your heart is stable. The stress test confirmed that. But please follow up with your cardiologist as planned."
    },
    {
      "turn_number": 21,
      "time": "2167-01-08 15:16:00",
      "speaker": "Patient",
      "text": "And the stress with my grandson?"
    },
    {
      "turn_number": 22,
      "time": "2167-01-08 15:18:00",
      "speaker": "Doctor",
      "text": "We’ve connected you with social work. You’re already seeing a therapist, which is great. Please keep going—that support is important."
    },
    {
      "turn_number": 23,
      "time": "2167-01-08 15:20:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I was so scared it was my heart again."
    },
    {
      "turn_number": 24,
      "time": "2167-01-08 15:22:00",
      "speaker": "Doctor",
      "text": "I understand. But the tests are clear. Take your meds, rest, and call if you have chest pain, shortness of breath, or new concerns."
    },
    {
      "turn_number": 25,
      "time": "2167-01-08 15:24:00",
      "speaker": "Patient",
      "text": "I will. And thank you for listening."
    },
    {
      "turn_number": 26,
      "time": "2167-01-08 15:26:00",
      "speaker": "Doctor",
      "text": "Of course. You’re going home in good condition. Just keep up with your follow-ups."
    },
    {
      "turn_number": 27,
      "time": "2167-01-08 15:28:00",
      "speaker": "Patient",
      "text": "I’ll do that."
    },
    {
      "turn_number": 28,
      "time": "2167-01-08 15:30:00",
      "speaker": "Doctor",
      "text": "Alright, the discharge papers are ready. You can head home soon."
    }
  ],
  "summary": {
    "admission_start": "2167-01-08 01:26:00",
    "admission_end": "2167-01-08 16:02:00",
    "summary_paragraph": "A 70-year-old woman with a history of coronary artery disease, prior CABG, GERD, and anxiety was admitted for two days of constant epigastric discomfort described as similar to her pre-bypass symptoms. Initial concern for cardiac ischemia was ruled out by normal EKGs, undetectable troponin levels on two occasions, and a normal exercise stress test. Her symptoms improved with pantoprazole, supporting a diagnosis of dyspepsia. She was found to have elevated blood pressure during admission, prompting an increase in lisinopril from 5mg to 10mg. Her anxiety, exacerbated by significant social stressors including her grandson’s uncertain living situation, was addressed with ongoing therapy and social work support. She remained stable throughout her stay, was discharged home on updated medications, and advised to follow up with her cardiologist and primary care provider.",
    "problems": [
      "Dyspepsia and other specified disorders of function of stomach",
      "Anxiety state, unspecified",
      "Coronary atherosclerosis of unspecified type of vessel, native or graft",
      "Aortocoronary bypass status",
      "Esophageal reflux",
      "Unspecified acquired hypothyroidism",
      "Other and unspecified hyperlipidemia",
      "Osteoporosis, unspecified"
    ]
  }
}
